(() => {
  'use strict';
  const P=window.Portal;if(!P)return;
  const e=P.e, rates=new Map(), prefix=P.demoMode?'partnerlabb.demo.propertyRate.v1.':'partnerlabb.propertyRate.v1.';
  const allowed=id=>P.getPartner(id)?.type==='property'&&(P.role==='internal'||P.role==='partner'&&P.partner===id);
  const money=n=>n==null?'—':new Intl.NumberFormat('sv-SE',{maximumFractionDigits:2}).format(n)+' kr';
  function rate(id){if(!rates.has(id)){let v=null;try{const raw=sessionStorage.getItem(prefix+id);if(raw!==null&&raw.trim()!==''&&Number.isFinite(+raw)&&+raw>=0)v=+raw;}catch{}rates.set(id,v);}return rates.get(id);}
  function calculate(id,month,value=rate(id)){
    const D=P.partnerResultsData,index=D?.months.indexOf(month),entries=D?.fixtureModel.activeEntries[id];
    const available=index>=0&&Array.isArray(entries)&&Number.isInteger(entries[index]);
    const activated=available?entries[index]:null;
    const valid=value!==null&&Number.isFinite(value)&&value>=0;
    return {month,activated,available,rate:valid?value:null,amount:available&&valid?Math.round(activated*value*100)/100:null,partial:month===D?.cutoff.slice(0,7),source:'Separat fiktivt aktiveringsunderlag'};
  }
  function total(id,months){const rows=[...new Set(months)].sort().map(m=>calculate(id,m));return {rows,activated:rows.filter(r=>r.available).reduce((s,r)=>s+r.activated,0),complete:rows.every(r=>r.available),amount:rows.every(r=>r.amount!==null)?rows.reduce((s,r)=>s+r.amount,0):null};}
  function waterfall(id,months){
    const D=P.partnerResultsData,known=months.filter(m=>D?.months.includes(m));
    if(!known.length||!D?.fixtureModel.activeEntries[id])return '<section class="card"><h2>Från aktiva avtal till nya aktiveringar</h2><p>Aktiverings- och beståndsunderlag saknas.</p></section>';
    const c=D.cohort({partnerIds:[id],months:known}),f=D.fixtureModel;
    const added=known.reduce((s,m)=>s+f.activeEntries[id][D.months.indexOf(m)],0);
    const exited=known.reduce((s,m)=>s+f.openingExits[id][D.months.indexOf(m)],0)+Object.entries(f.laterExits[id]||{}).reduce((s,[,exits])=>s+known.reduce((a,m)=>a+(exits[m]||0),0),0);
    const final=c.openingActive+added-exited,max=Math.max(1,c.openingActive+added),bars=[['Aktiva vid start',c.openingActive,0,c.openingActive],['Aktiverade',added,c.openingActive,added],['Avslutade',exited,final,exited],['Aktiva vid slut',final,0,final]];
    return `<section class="card pc-waterfall"><h2>Avtalsutveckling</h2><p>Bestånd och händelser under ${e(P.periodSet.summary('month',known))}. ${known.length!==months.length?'Diagrammet omfattar bara månader med underlag. ':''}${known.includes('2026-10')?'Oktober är en delperiod till 7 oktober.':''}</p><div class="pc-bars" role="img" aria-label="${e(bars.map(b=>b[0]+': '+b[1]).join(', '))}">${bars.map(([label,n,start,height],i)=>`<div class="pc-bar"><strong>${n}</strong><div class="pc-track"><i class="pc-bar-${i}" style="bottom:${start/max*100}%;height:${height/max*100}%"></i></div><span>${label}</span></div>`).join('')}</div><p><strong>Endast nya aktiveringar ger ersättning.</strong> Aktiva avtal vid periodens början räknas inte igen. Avslutade avtal visas som beståndsförändring; inget automatiskt återkrav ingår i denna modell.</p></section>`;
  }
  function detail(id,month){const c=calculate(id,month);return `<div class="oc-calculation"><h3>Fast ersättning per aktiverat avtal</h3><p>${c.available?c.activated:'—'} aktiverade avtal × ${money(c.rate)} = <strong>${money(c.amount)}</strong>.</p><p>Avtalet räknas en gång, i månaden då elhandelsleveransen aktiveras. Registrering, godkännande och bindande avtal ger ingen ersättning före aktiveringen. Inga förskott eller förskottsavräkningar används.</p><p>${c.partial?'Delperiod: 1–7 oktober 2026. ':''}Belopp exkl. moms. Det angivna beloppet per avtal är ett lokalt beräkningsvärde, inte verifierade avtalsvillkor.</p><p>Aktiveringarna är separat angivna månadsaggregat i demot. Individuella avtals-ID:n finns inte i detta underlag. Testregistrerade inflyttningar och visningsel räknas inte automatiskt in.</p><p>Fakturering och betalningar måste stämmas av separat. Exporten skickar ingen faktura.</p></div>`;}
  function render(id,months){
    if(!allowed(id))return '';
    const t=total(id,months),value=rate(id);
    return `<div class="pc-commission" data-pc-partner="${e(id)}">${waterfall(id,months)}<section class="oc-period-overview card"><header><h2>Provision och fakturaunderlag</h2><p>En rad per aktiveringsmånad. Fast ersättning per aktiverat elhandelsavtal, utan förskott.</p></header><form data-pc-rate-form class="pc-rate"><label class="field">Ersättning per aktiverat avtal, kr<input name="rate" type="number" min="0" step="0.01" required value="${value??''}" placeholder="Ange belopp" inputmode="decimal"></label><button class="btn btn-secondary" type="submit">Beräkna</button><p role="alert"></p></form><p>Beloppet används som ett lokalt beräkningsvärde för den här partnern. Det ändrar inga avtalsvillkor. Samma belopp används för de valda månaderna.</p><div class="property-results-payment"><div><span>Nya aktiveringar med underlag</span><strong>${t.rows.some(r=>r.available)?t.activated:'—'}</strong></div><div><span>Beräknad ersättning exkl. moms</span><strong data-pc-total>${money(t.amount)}</strong><small>${!t.complete?'Underlag saknas för delar av perioden.':value===null?'Ange ersättning per aktiverat avtal.':'Antal aktiveringar × belopp per avtal.'}</small></div></div><div class="table-wrap"><table class="oc-monthly-table"><thead><tr><th>Månad</th><th>Aktiverade avtal</th><th>Kr per avtal</th><th>Total provision</th><th>Underlag</th></tr></thead><tbody>${t.rows.map(c=>`<tr data-pc-month="${c.month}"><th scope="row">${e(P.periodSet.summary('month',[c.month]))}${c.partial?'<small>Delperiod · 1–7 oktober</small>':''}</th><td data-label="Aktiverade avtal">${c.activated??'—'}</td><td data-label="Kr per avtal">${money(c.rate)}</td><td data-label="Total provision">${c.available?(c.amount===null?'Ange ersättning':money(c.amount)):'Underlag saknas'}</td><td class="pc-actions"><div class="oc-row-actions"><button class="text-button" data-pc-detail="${c.month}">Visa beräkning</button><button class="btn btn-secondary" data-pc-export="${c.month}" ${c.amount===null?'disabled':''}>Fakturaunderlag (Excel)</button></div><span role="status" data-pc-status="${c.month}"></span></td></tr>`).join('')}</tbody></table></div><p>Preliminärt beräkningsunderlag. Tidigare fakturering och genomförda betalningar ingår inte. Månader utan aktiveringsunderlag visas som saknade, inte som noll.</p></section></div>`;
  }
  function buildWorkbook(id,month){
    if(!allowed(id))throw Error('Underlaget är inte tillgängligt för den här partnern.');
    const c=calculate(id,month);if(c.amount===null)throw Error('Komplettera aktiveringsunderlag och ersättning per avtal.');
    if(!window.ExcelJS?.Workbook)throw Error('Excel-exporten kunde inte laddas.');
    const book=new window.ExcelJS.Workbook(),sheet=book.addWorksheet('Fakturaunderlag'),basis=book.addWorksheet('Beräkningsgrund');
    sheet.addRows([['PRELIMINÄRT FAKTURAUNDERLAG – EXEMPELDATA'],[P.getPartner(id).name],['Aktiveringsmånad',month],[],['Underlag','Antal','Kr per avtal','Ersättning exkl. moms'],['Aktiverade elhandelsavtal',c.activated,c.rate,{formula:'B6*C6',result:c.amount}],[],['Förskott',0],['Delperiod',c.partial?'1–7 oktober 2026':'Nej'],['Tidigare fakturering och betalningar','Stäms av separat'],['Lokalt beräkningsvärde','Inga verifierade avtalsvillkor'],['Exporten skickar ingen faktura']]);
    basis.addRows([['Partner','Månad','Aktiverade avtal','Belopp per avtal','Källa'],[P.getPartner(id).name,month,c.activated,c.rate,c.source],[],['Beräkning','Aktiverade avtal × fast ersättning per avtal'],['Datumgrund','Aktiveringsmånad – inte registrering eller bindandedatum'],['Avtals-ID','Individuella ID:n saknas i det aggregerade exempelunderlaget'],['Avgränsning','Lokala serviceärenden och visningsel ger ingen automatisk kickback']]);
    for(const ws of [sheet,basis]){ws.columns=[{width:45},{width:30},{width:25},{width:28},{width:45}];ws.eachRow(r=>r.eachCell(c=>{c.font={name:'Arial',size:11};c.alignment={vertical:'top',wrapText:true};}));ws.getRow(1).font={bold:true,size:14,color:{argb:'FF003B50'}};ws.views=[{state:'frozen',ySplit:5}];}
    sheet.getCell('D6').numFmt='#,##0.00';sheet.getCell('C6').numFmt='#,##0.00';return book;
  }
  function bind(id){if(!allowed(id))return;const root=document.querySelector(`[data-pc-partner="${id}"]`);if(!root)return;
    root.querySelector('[data-pc-rate-form]').onsubmit=ev=>{ev.preventDefault();const form=ev.currentTarget;if(!form.reportValidity())return;const value=Number(form.elements.rate.value);if(!Number.isFinite(value)||value<0)return;try{sessionStorage.setItem(prefix+id,String(value));rates.set(id,value);P.render();}catch{form.querySelector('[role=alert]').textContent='Beloppet kunde inte sparas. Försök igen.';}};
    root.querySelectorAll('[data-pc-detail]').forEach(b=>b.onclick=()=>P.openDialog('Beräkning · '+P.periodSet.summary('month',[b.dataset.pcDetail]),detail(id,b.dataset.pcDetail)));
    root.querySelectorAll('[data-pc-export]').forEach(b=>b.onclick=async()=>{const month=b.dataset.pcExport,status=root.querySelector(`[data-pc-status="${month}"]`);b.disabled=true;try{const book=buildWorkbook(id,month),actor=P.prototypeUsers?.current()?.id;await P.saveExcel({filename:`fakturaunderlag-${id}-${month}.xlsx`,status,build:()=>book.xlsx.writeBuffer(),valid:()=>allowed(id)&&P.prototypeUsers?.current()?.id===actor});}catch(error){status.textContent=error.message;}finally{b.disabled=false;}});
  }
  P.propertyCommission={calculate,total,render,bind,buildWorkbook,rate,detail};
})();
